                let valid = id > 0
                    && self
                        .scene_access
                        .as_ref()
                        .map(|a| !matches!(a.get_node_property(id as u64, "name"), Variant::Nil))
                        .unwrap_or(false);
                Ok(Some(Variant::Bool(valid)))
