                // a zero draw is nudged to the smallest usable value rather than
                // producing a NaN the caller would have to discover at runtime.
                let u1 = {
                    let u = (deterministic_randi() as f64) / (i64::MAX as f64);
                    if u <= f64::EPSILON {
                        f64::EPSILON
                    } else {
                        u
                    }
                };
