                    let mut sign = 1i64;
                    if let Some(r) = t.strip_prefix('-') {
                        sign = -1;
                        t = r;
                    } else if let Some(r) = t.strip_prefix('+') {
                        t = r;
                    }
                    let t = t
                        .strip_prefix("0b")
                        .or_else(|| t.strip_prefix("0B"))
                        .unwrap_or(t);
