/// `PCKPacker` instance methods (pat-0q2kx.218).
///
/// Godot ground truth: `core/io/pck_packer.cpp`. Godot's `pck_start` opens the
/// output file and `flush` finishes it; Patina's engine accumulates in memory
/// and serializes on flush, so the destination path is remembered from
/// `pck_start` and used by `flush`.
fn call_pck_packer_instance(
    id: gdcore::ObjectId,
    method: &str,
    args: &[Variant],
) -> Result<Variant, RuntimeError> {
    use gdresource::pck::PckPacker;

    let out = match method {
        "pck_start" => {
            let path = arg_as_string(args, 0, "pck_start")?;
            let alignment = args.get(1).and_then(|v| match v {
                Variant::Int(i) => Some(*i as u64),
                _ => None,
            });
            // Stored on the interpreter side rather than the engine struct: the
            // engine's packer is a pure accumulator and giving it a path field
            // would mean a half-open file living across script calls.
            pck_packer_paths().insert(id.raw(), path);
            PckPacker::with_handle_mut(id, |p| {
                if let Some(a) = alignment {
                    // `with_alignment` consumes self, so swap through a clone of
                    // the accumulated state rather than rebuilding it.
                    let taken = std::mem::replace(p, PckPacker::new());
                    *p = taken.with_alignment(a);
                }
                Variant::Int(0)
            })
        }
        // Godot's signature is (pck_path, source_path, encrypt): the file's
        // bytes come from disk. `encrypt` is accepted and ignored — Patina's
        // pack format has no per-file encryption, and rejecting the argument
        // would break otherwise-valid scripts.
        "add_file" => {
            if args.len() < 2 {
                return Err(RuntimeError::new(RuntimeErrorKind::TypeError(
                    "PCKPacker.add_file() takes at least 2 arguments".into(),
                )));
            }
            let pck_path = arg_as_string(args, 0, "add_file")?;
            let source = arg_as_string(args, 1, "add_file")?;
            let data = match gdcore::FileAccess::open(&source, gdcore::FileMode::Read).and_then(
                |mut fa| {
                    // No whole-file byte read on FileAccess; length-then-read is
                    // the same pair Godot's `get_buffer(get_length())` uses.
                    let len = fa.get_length()? as usize;
                    fa.get_buffer(len)
                },
            ) {
                Ok(d) => d,
                // ERR_FILE_CANT_OPEN
                Err(_) => return Ok(Variant::Int(12)),
            };
            PckPacker::with_handle_mut(id, |p| {
                p.add_file(pck_path, data);
                Variant::Int(0)
            })
        }
        "get_file_count" => PckPacker::with_handle_mut(id, |p| Variant::Int(p.file_count() as i64)),
        "flush" => {
            let Some(path) = pck_packer_paths().get(&id.raw()).cloned() else {
                return Err(RuntimeError::new(RuntimeErrorKind::TypeError(
                    "PCKPacker.flush() called before pck_start()".into(),
                )));
            };
            PckPacker::with_handle_mut(id, |p| {
                Variant::Int(match p.flush_to_path(&path) {
                    Ok(()) => 0,
                    Err(_) => 14,
                })
            })
        }
        other => {
            return Err(RuntimeError::new(RuntimeErrorKind::UndefinedFunction(
                format!("PCKPacker.{other}"),
            )))
        }
    };
    out.ok_or_else(|| dead_handle("PCKPacker", method))
}

/// Destination paths remembered by `PCKPacker.pck_start`, keyed by handle.
fn pck_packer_paths() -> std::sync::MutexGuard<'static, HashMap<u64, String>> {
    static PATHS: OnceLock<Mutex<HashMap<u64, String>>> = OnceLock::new();
    PATHS
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// Prefix of the synthetic method name a lambda signal connection is stored
/// under (pat-s3rrv.67).
const LAMBDA_CONNECTION_PREFIX: &str = "__lambda_connection_";

thread_local! {
    /// Lambda `Callable`s parked in node signal connections, keyed by the
    /// numeric suffix of their synthetic method name (pat-s3rrv.67).
    ///
    /// ⚠️ **Why a registry rather than storing the Callable.** A
    /// `gdobject::signal::Connection` is `(target_id, method_NAME)` — a name,
    /// not a `Callable` — so `sig.connect(func(): ...)` had nowhere to be
    /// stored at all and [`callable_target`] returned `None`, surfacing as
    /// `connect() Callable has no bindable target/method`. Godot connects
    /// lambdas routinely (`GDScriptLambdaCallable` is just another
    /// `CallableCustom`), so the connection is recorded under a generated name
    /// and resolved back here when the signal fires.
    ///
    /// ⚠️ **Entries are never removed, and that is deliberate.** A connection
    /// outlives the expression that created it and nothing in the `SignalStore`
    /// reports a disconnect back to the interpreter, so a removal here could
    /// only ever be a guess. The map grows by one per *distinct* lambda
    /// connected — [`lambda_connection_name`] reuses the existing entry for a
    /// Callable it has already seen — so reconnecting the same lambda in a
    /// per-frame handler does not accumulate.
    static LAMBDA_CONNECTIONS: std::cell::RefCell<HashMap<u64, CallableRef>> =
        std::cell::RefCell::new(HashMap::new());
    /// Id sequence for [`LAMBDA_CONNECTIONS`]. Separate from the map's `len()`
    /// so that ids stay unique even if a future change does start removing.
    static LAMBDA_CONNECTION_SEQ: std::cell::Cell<u64> = std::cell::Cell::new(0);
}

/// The synthetic method name `callable` is connected under, registering it on
/// first use (pat-s3rrv.67).
///
/// ⚠️ **Find-or-insert, not insert.** `connect`, `disconnect` and
/// `is_connected` all resolve their argument through [`callable_target`], so a
/// name that changed per call would make `sig.disconnect(cb)` silently fail and
/// `sig.is_connected(cb)` always answer false — the caller would be handing the
/// `SignalStore` a name it never stored. Matching on `CallableRef`'s `PartialEq`
/// is what keeps the three in agreement, and for a lambda that equality is
/// identity of the body `Arc` — Godot's own rule
/// (`gdscript_lambda_callable.cpp:37-40`). A *freshly written* `func(): ...` is
/// a different lambda and correctly gets its own name, exactly as it would in
/// Godot.
///
/// The scan is linear in the number of distinct connected lambdas, which is
/// bounded by the script's own `connect` calls.
fn lambda_connection_name(callable: &CallableRef) -> String {
    LAMBDA_CONNECTIONS.with(|m| {
        let mut map = m.borrow_mut();
        let existing = map.iter().find(|(_, c)| *c == callable).map(|(id, _)| *id);
        if let Some(id) = existing {
            return format!("{}{}", LAMBDA_CONNECTION_PREFIX, id);
        }
        let id = LAMBDA_CONNECTION_SEQ.with(|seq| {
            let next = seq.get();
            seq.set(next + 1);
            next
        });
        map.insert(id, callable.clone());
        format!("{}{}", LAMBDA_CONNECTION_PREFIX, id)
    })
}

/// Whether `name` is a synthetic lambda-connection method name (pat-s3rrv.67).
///
/// ⚠️ **A `has_method` that answers `false` here silently breaks every
/// signal-connected lambda.** `SceneTree::call_script_method` skips any method
/// the script does not define — right, because lifecycle dispatch calls
/// `_ready`/`_process` on every node blindly — and a `__lambda_connection_N`
/// name is deliberately *not* in `class_def.methods`. So the guard returned
/// early and the lambda never reached [`Interpreter::call_instance_method`],
/// which is the only place that can resolve it. The connection stored fine and
/// the emit did nothing, which reads as "capture is broken" rather than "the
/// dispatch gate rejected the name".
///
/// Kept public so the scene layer can widen that gate without knowing the
/// prefix, which stays private here.
pub fn is_lambda_connection_name(name: &str) -> bool {
    name.strip_prefix(LAMBDA_CONNECTION_PREFIX)
        .is_some_and(|id| id.parse::<u64>().is_ok())
}

/// The `Callable` a synthetic connection method name resolves to, or `None` for
/// an ordinary script method name (pat-s3rrv.67).
fn lambda_connection(method_name: &str) -> Option<CallableRef> {
    let id: u64 = method_name
        .strip_prefix(LAMBDA_CONNECTION_PREFIX)?
        .parse()
        .ok()?;
    LAMBDA_CONNECTIONS.with(|m| m.borrow().get(&id).cloned())
}

/// Returns `true` if the identifier is a known Godot node class name that
/// supports `.new()` for runtime instantiation.
/// Resolves the `(target_object, method_name)` a signal connection should
/// store from a `Callable` argument (pat-0q2kx.9).
///
/// `Callable(self, "m")` records `target_id == 0` meaning "the calling object",
/// so an explicit 0 resolves against `self_node`. A plain String/StringName is
/// also accepted: Patina scripts predate first-class Callables, and Godot 3's
/// `connect(sig, obj, "method")` form still reaches here through the
/// object-level `connect` arm.
fn callable_target(v: &Variant, self_node: Option<u64>) -> Option<(u64, String)> {
    match v {
        Variant::Callable(c) => match c.inner_callable() {
            CallableRef::Method { target_id, method } => {
                let target = if *target_id == 0 {
                    self_node?
                } else {
                    *target_id
                };
                Some((target, method.clone()))
            }
            // A lambda has no method NAME, and a `SignalStore` `Connection`
            // stores a name rather than a `Callable` — so it is parked in a
            // side registry and connected under a generated one that
            // `call_instance_method` resolves back at dispatch time
            // (pat-s3rrv.67).
            //
            // ⚠️ The target is the CONNECTING script's own node. That is not an
            // arbitrary choice: it is what makes `self` inside the lambda body
            // resolve to the instance that wrote the lambda, because the
            // dispatch goes through that node's script and installs it as
            // `self_instance`. A lambda has no target of its own to name.
            //
            // ⚠️ Registers the OUTER callable, not the `inner_callable()` this
            // match ran on: `func(): ...` .bind(x) arrives here as
            // `Bound { inner: Lambda, .. }`, and registering the unwrapped
            // Lambda would drop the bound arguments.
            CallableRef::Lambda { .. } => Some((self_node?, lambda_connection_name(&**c))),
            _ => None,
        },
        Variant::String(s) => Some((self_node?, s.clone())),
        Variant::StringName(s) => Some((self_node?, s.as_str().to_string())),
        _ => None,
    }
}

/// The pre-ClassDB hardcoded list, kept as a FALLBACK (pat-s3rrv.57).
///
/// ⚠️ Do not delete this in favour of the ClassDB query alone. ClassDB is a
/// process-global that is **not populated implicitly** — a unit test, or any
/// host that never calls a `register_*_classes` entry point, sees it empty, and
/// a purely ClassDB-driven predicate would answer `false` for everything and
/// silently un-break `Sprite2D.new()` for those callers. Keeping the literal
/// list as an OR-ed floor means the generic path can only ever ADD classes.
fn is_legacy_node_class_name(name: &str) -> bool {
    matches!(
        name,
        "Node"
            | "Node2D"
            | "Node3D"
            | "Control"
            | "Sprite2D"
            | "Sprite3D"
            | "Area2D"
            | "Area3D"
            | "CharacterBody2D"
            | "CharacterBody3D"
            | "RigidBody2D"
            | "RigidBody3D"
            | "StaticBody2D"
            | "StaticBody3D"
            | "CollisionShape2D"
            | "CollisionShape3D"
            | "Timer"
            | "Camera2D"
            | "Camera3D"
            | "Label"
            | "Button"
            | "TextureRect"
            | "AudioStreamPlayer"
            | "AnimationPlayer"
            | "CanvasLayer"
            | "ColorRect"
            // Godot's navigation agents inherit `Node`, so a script may
            // construct one and add it under a body exactly like any other node
            // (pat-s3rrv.20). Omitting them here made `NavigationAgent2D.new()`
            // fail before a single method could be called on the result.
            | "NavigationAgent2D"
            | "NavigationAgent3D"
    )
}

/// Whether `name` is a class a script may construct with `.new()` and add to
/// the tree — asked of ClassDB rather than of a 26-name list (pat-s3rrv.57).
///
/// Godot resolves `SomeClass.new()` through `ClassDB::instantiate`, which works
/// for every non-abstract registered class. Patina answered it from a literal
/// `matches!`, so `AnimatedSprite2D.new()`, `Line2D.new()`, `VBoxContainer.new()`,
/// `MeshInstance3D.new()` and hundreds more raised `UndefinedVariable` despite
/// being registered — the class existed, the script just could not say its name.
///
/// The three conditions are Godot's own: registered, not abstract, and derived
/// from `Node` (the tree-insertable half; RefCounted types are served by the
/// bespoke handle arms above this call).
fn is_node_class_name(name: &str) -> bool {
    if is_legacy_node_class_name(name) {
        return true;
    }
    gdobject::class_db::class_exists(name)
        && !gdobject::class_db::is_abstract(name)
        && gdobject::class_db::is_parent_class(name, "Node")
}

// ---------------------------------------------------------------------------
// pat-s3rrv.14: the InputEvent instance-method surface.
//
// The 17-class family and object delivery landed in earlier passes: a script's
// `_input(event)` already receives a `Variant::Resource` whose `class_name` is
// `InputEventKey` / `InputEventMouseButton` / …, and `event is InputEventKey`
// already type-checks through ClassDB. What had NO implementation anywhere in
// the workspace was the METHODS — `is_pressed`, `is_echo`, `as_text` and, above
// all, `event.is_action_pressed("ui_accept")`, which is the single most common
// line in any Godot `_input` body. They were registered in ClassDB as metadata
// and dispatched by nothing.
//
// Every rule below is transcribed from upstream/godot/core/input/input_event.cpp
// and input_map.cpp rather than inferred from the method names, because several
// of them are counter-intuitive: `is_released()` is `!pressed && !canceled`
// (NOT `!is_pressed()`, so a canceled event is neither), the modifier order in
// `as_text()` is Ctrl+Alt+Shift+Meta, and an `InputEventAction` short-circuits
// action matching on its own action name instead of consulting the InputMap's
// bindings at all.
// ---------------------------------------------------------------------------

/// The method names the InputEvent arm implements.
///
/// Kept as an explicit list rather than a catch-all so a method Patina has not
/// implemented reaches the general resource table and, failing there, raises —
/// which is far easier to diagnose than a silent `Nil`.
fn is_input_event_method(method: &str) -> bool {
    matches!(
        method,
        "is_pressed"
            | "is_released"
            | "is_echo"
            | "is_canceled"
            | "is_action_type"
            | "as_text"
            | "get_device"
            | "is_action"
            | "is_action_pressed"
            | "is_action_released"
            | "get_action_strength"
            | "get_action_raw_strength"
            | "is_match"
            | "get_modifiers_mask"
            | "is_command_or_control_pressed"
            | "as_text_keycode"
            | "as_text_physical_keycode"
            | "as_text_key_label"
            | "get_keycode_with_modifiers"
            | "get_physical_keycode_with_modifiers"
            | "xformed_by"
    )
}

/// Godot's `KeyModifierMask` values (upstream/godot/core/os/keyboard.h:249).
const GODOT_MOD_SHIFT: i64 = 1 << 25;
const GODOT_MOD_ALT: i64 = 1 << 26;
const GODOT_MOD_META: i64 = 1 << 27;
const GODOT_MOD_CTRL: i64 = 1 << 28;

/// Whether `class_name` is somewhere in the InputEvent hierarchy.
///
/// Answered from the NAME rather than by walking ClassDB, deliberately: ClassDB
/// is a process-global that starts empty and a unit test that never calls
/// `register_all_classes()` would otherwise see every event method silently
/// stop dispatching. Every class in Godot's hierarchy carries the prefix, and
/// no class outside it does.
fn is_input_event_class(class_name: &str) -> bool {
    class_name.starts_with("InputEvent")
}

fn ie_bool(res: &gdvariant::ResourceRef, key: &str) -> bool {
    matches!(res.properties.get(key), Some(Variant::Bool(true)))
}

fn ie_int(res: &gdvariant::ResourceRef, key: &str) -> i64 {
    match res.properties.get(key) {
        Some(Variant::Int(i)) => *i,
        Some(Variant::Float(f)) => *f as i64,
        _ => 0,
    }
}

fn ie_float(res: &gdvariant::ResourceRef, key: &str) -> f64 {
    match res.properties.get(key) {
        Some(Variant::Float(f)) => *f,
        Some(Variant::Int(i)) => *i as f64,
        _ => 0.0,
    }
}

fn ie_string(res: &gdvariant::ResourceRef, key: &str) -> String {
    match res.properties.get(key) {
        Some(Variant::String(s)) => s.clone(),
        _ => String::new(),
    }
}

/// `InputEvent::is_pressed()` — `pressed && !canceled` (input_event.cpp:79).
fn ie_is_pressed(res: &gdvariant::ResourceRef) -> bool {
    ie_bool(res, "pressed") && !ie_bool(res, "canceled")
}

/// `InputEvent::is_released()` — `!pressed && !canceled` (input_event.cpp:83).
///
/// Deliberately NOT `!is_pressed()`: a canceled event is neither pressed nor
/// released, and the two predicates are false together for it.
fn ie_is_released(res: &gdvariant::ResourceRef) -> bool {
    !ie_bool(res, "pressed") && !ie_bool(res, "canceled")
}

/// `InputEvent::is_echo()` — false on the base, `echo` on InputEventKey only
/// (input_event.cpp:87 / :386).
fn ie_is_echo(res: &gdvariant::ResourceRef) -> bool {
    res.class_name == "InputEventKey" && ie_bool(res, "echo")
}

/// `InputEvent::is_action_type()` — false on the base, overridden to true on
/// exactly five classes (input_event.h:190/254/324/354/473).
///
/// ⚠️ InputEventScreenTouch is NOT one of them, which is easy to assume it is.
fn ie_is_action_type(class_name: &str) -> bool {
    matches!(
        class_name,
        "InputEventKey"
            | "InputEventMouseButton"
            | "InputEventJoypadMotion"
            | "InputEventJoypadButton"
            | "InputEventAction"
    )
}

/// `InputEventWithModifiers::get_modifiers_mask()` (input_event.cpp).
fn ie_modifiers_mask(res: &gdvariant::ResourceRef) -> i64 {
    let mut mask = 0;
    if ie_bool(res, "ctrl_pressed") {
        mask |= GODOT_MOD_CTRL;
    }
    if ie_bool(res, "shift_pressed") {
        mask |= GODOT_MOD_SHIFT;
    }
    if ie_bool(res, "alt_pressed") {
        mask |= GODOT_MOD_ALT;
    }
    if ie_bool(res, "meta_pressed") {
        mask |= GODOT_MOD_META;
    }
    mask
}

/// `InputEventWithModifiers::as_text()` — Ctrl, Alt, Shift, Meta in THAT order,
/// joined with `+` (input_event.cpp:257).
fn ie_modifier_text(res: &gdvariant::ResourceRef) -> String {
    let mut parts: Vec<&str> = Vec::new();
    if ie_bool(res, "ctrl_pressed") {
        parts.push("Ctrl");
    }
    if ie_bool(res, "alt_pressed") {
        parts.push("Alt");
    }
    if ie_bool(res, "shift_pressed") {
        parts.push("Shift");
    }
    if ie_bool(res, "meta_pressed") {
        parts.push("Meta");
    }
    parts.join("+")
}

/// Godot's `keycode_get_string` for the keycodes Patina can produce.
///
/// ⚠️ Transcribed from upstream/godot/core/os/keyboard.cpp `_keycodes[]`, NOT
/// from `gdplatform::input::Key::name()`. That method returns BROWSER
/// `KeyboardEvent.key` names — `"ArrowUp"`, and `" "` for space — where Godot
/// says `"Up"` and `"Space"`. Reusing it would have produced text that looks
/// right and matches nothing a Godot project prints.
fn godot_keycode_name(code: i64) -> String {
    // Letters and digits are their ASCII selves in Godot's numbering.
    if (65..=90).contains(&code) || (48..=57).contains(&code) {
        return ((code as u8) as char).to_string();
    }
    let special = match code {
        32 => "Space",
        4194305 => "Escape",
        4194306 => "Tab",
        4194307 => "Backtab",
        4194308 => "Backspace",
        4194309 => "Enter",
        4194310 => "Kp Enter",
        4194311 => "Insert",
        4194312 => "Delete",
        4194317 => "Home",
        4194318 => "End",
        4194319 => "Left",
        4194320 => "Up",
        4194321 => "Right",
        4194322 => "Down",
        4194323 => "PageUp",
        4194324 => "PageDown",
        4194325 => "Shift",
        4194326 => "Ctrl",
        4194327 => "Meta",
        4194328 => "Alt",
        4194329 => "CapsLock",
        4194330 => "NumLock",
        4194331 => "ScrollLock",
        _ => "",
    };
    if !special.is_empty() {
        return special.to_string();
    }
    // F1..F16 run contiguously from SPECIAL|0x1C.
    if (4194332..=4194347).contains(&code) {
        return format!("F{}", code - 4194331);
    }
    // Anything else keeps its numeric identity rather than inventing a name.
    format!("{code}")
}

/// `InputEventKey::as_text_keycode` / `_physical_keycode` / `_key_label`, which
/// share one shape: the named code, prefixed with the modifier text.
fn ie_keycode_text(res: &gdvariant::ResourceRef, field: &str) -> String {
    let code = ie_int(res, field);
    let kc = if code == 0 {
        "(unset)".to_string()
    } else {
        godot_keycode_name(code)
    };
    let mods = ie_modifier_text(res);
    if mods.is_empty() {
        kc
    } else {
        format!("{mods}+{kc}")
    }
}

/// Godot's `_mouse_button_descriptions` (input_event.cpp:810), 1-indexed.
fn godot_mouse_button_name(index: i64) -> String {
    match index {
        1 => "Left Mouse Button".to_string(),
        2 => "Right Mouse Button".to_string(),
        3 => "Middle Mouse Button".to_string(),
        4 => "Mouse Wheel Up".to_string(),
        5 => "Mouse Wheel Down".to_string(),
        6 => "Mouse Wheel Left".to_string(),
        7 => "Mouse Wheel Right".to_string(),
        8 => "Mouse Thumb Button 1".to_string(),
        9 => "Mouse Thumb Button 2".to_string(),
        other => format!("Button #{other}"),
    }
}

/// `InputEvent::as_text()` for the classes Patina delivers.
fn ie_as_text(res: &gdvariant::ResourceRef) -> String {
    let mods = ie_modifier_text(res);
    match res.class_name.as_str() {
        "InputEventKey" => {
            let kc = godot_keycode_name(ie_int(res, "keycode"));
            if mods.is_empty() {
                kc
            } else {
                format!("{mods}+{kc}")
            }
        }
        "InputEventMouseButton" => {
            let prefix = if mods.is_empty() {
                String::new()
            } else {
                format!("{mods}+")
            };
            let name = godot_mouse_button_name(ie_int(res, "button_index"));
            if ie_bool(res, "double_click") {
                format!("{prefix}{name} (Double Click)")
            } else {
                format!("{prefix}{name}")
            }
        }
        "InputEventAction" => {
            let action = ie_string(res, "action");
            let state = if ie_is_pressed(res) {
                "pressed"
            } else {
                "released"
            };
            format!("Input Action: action={action}, pressed={state}")
        }
        other => other.to_string(),
    }
}

/// Rebuilds an `InputEvent` object from a binding spec (pat-s3rrv.14).
///
/// This is what lets `InputMap.action_get_events` return real events. The
/// result carries only what a BINDING knows — a binding has no press state, so
/// `pressed` is false, exactly as Godot's stored binding events are.
fn input_event_from_spec(spec: &crate::bindings::InputEventSpec) -> Variant {
    let mut properties = std::collections::HashMap::new();
    properties.insert("device".to_string(), Variant::Int(0));
    properties.insert("pressed".to_string(), Variant::Bool(false));
    properties.insert("canceled".to_string(), Variant::Bool(false));
    match spec.class.as_str() {
        "InputEventKey" => {
            properties.insert("keycode".to_string(), Variant::Int(spec.code));
            properties.insert("physical_keycode".to_string(), Variant::Int(spec.code));
            properties.insert("key_label".to_string(), Variant::Int(spec.code));
            properties.insert("unicode".to_string(), Variant::Int(0));
            properties.insert("location".to_string(), Variant::Int(0));
            properties.insert("echo".to_string(), Variant::Bool(false));
        }
        "InputEventMouseButton" => {
            properties.insert("button_index".to_string(), Variant::Int(spec.code));
            properties.insert("double_click".to_string(), Variant::Bool(false));
            properties.insert("factor".to_string(), Variant::Float(1.0));
        }
        "InputEventJoypadButton" => {
            properties.insert("button_index".to_string(), Variant::Int(spec.code));
            properties.insert("pressure".to_string(), Variant::Float(0.0));
        }
        "InputEventJoypadMotion" => {
            properties.insert("axis".to_string(), Variant::Int(spec.code));
            properties.insert(
                "axis_value".to_string(),
                Variant::Float(spec.axis_value as f64),
            );
        }
        _ => {}
    }
    properties.insert("shift_pressed".to_string(), Variant::Bool(spec.shift));
    properties.insert("ctrl_pressed".to_string(), Variant::Bool(spec.ctrl));
    properties.insert("alt_pressed".to_string(), Variant::Bool(spec.alt));
    properties.insert("meta_pressed".to_string(), Variant::Bool(false));
    Variant::Resource(Box::new(gdvariant::ResourceRef {
        path: String::new(),
        class_name: spec.class.clone(),
        properties,
    }))
}

/// The binding shape an event presents to InputMap matching, or `None` for an
/// event kind no action can be bound to (mouse motion, gestures, …).
fn ie_to_spec(res: &gdvariant::ResourceRef) -> Option<crate::bindings::InputEventSpec> {
    let (class, code, axis_value) = match res.class_name.as_str() {
        "InputEventKey" => ("InputEventKey", ie_int(res, "keycode"), 0.0),
        "InputEventMouseButton" => ("InputEventMouseButton", ie_int(res, "button_index"), 0.0f32),
        "InputEventJoypadButton" => ("InputEventJoypadButton", ie_int(res, "button_index"), 0.0),
        "InputEventJoypadMotion" => (
            "InputEventJoypadMotion",
            ie_int(res, "axis"),
            ie_float(res, "axis_value") as f32,
        ),
        _ => return None,
    };
    Some(crate::bindings::InputEventSpec {
        class: class.to_string(),
        code,
        axis_value,
        shift: ie_bool(res, "shift_pressed"),
        ctrl: ie_bool(res, "ctrl_pressed"),
        alt: ie_bool(res, "alt_pressed"),
    })
}

/// Whether `binding` matches `event`, following `InputEvent*::action_match`.
///
/// With `exact_match` false — Godot's default — modifiers are IGNORED, so a
/// plain `W` binding fires for `Ctrl+W`. That is deliberate upstream: it is the
/// whole reason `exact_match` exists as a parameter.
fn ie_binding_matches(
    binding: &crate::bindings::InputEventSpec,
    event: &gdvariant::ResourceRef,
    event_spec: &crate::bindings::InputEventSpec,
    exact_match: bool,
) -> bool {
    if binding.class != event_spec.class {
        return false;
    }
    if binding.code != event_spec.code {
        return false;
    }
    if binding.class == "InputEventJoypadMotion" {
        // A binding only presses on deflection with its own sign
        // (upstream InputEventJoypadMotion::action_match).
        if binding.axis_value.signum() != event_spec.axis_value.signum() {
            return false;
        }
    }
    if exact_match {
        let want = (binding.shift as i64) * GODOT_MOD_SHIFT
            + (binding.ctrl as i64) * GODOT_MOD_CTRL
            + (binding.alt as i64) * GODOT_MOD_ALT;
        return want == ie_modifiers_mask(event);
    }
    true
}

fn variant_eq(a: &Variant, b: &Variant) -> bool {
    match (a, b) {
        // Godot compares int and float numerically across the two types
        // (`Variant::evaluate` OP_EQUAL promotes), so `1 == 1.0` is true.
        (Variant::Int(a), Variant::Float(b)) => (*a as f64) == *b,
        (Variant::Float(a), Variant::Int(b)) => *a == (*b as f64),
        // Everything else compares structurally.
        //
        // This arm used to be `_ => false`, which enumerated only Nil/Bool/Int/
        // Float/String/Vector2/Vector3/Color and silently answered *false* for
        // every other pair — two equal Dictionaries, Arrays, Vector2is,
        // Quaternions, Transforms or packed arrays never compared equal, so
        // `==` was not merely incomplete but actively wrong (pat-0q2kx.153).
        //
        // `Variant`'s derived `PartialEq` is structural and already returns
        // false for mismatched kinds, and `Dictionary`'s hand-written impl is
        // order-independent — which is what Godot's recursive `==` does.
        _ => a == b,
    }
}

// ---------------------------------------------------------------------------
// GDScriptInstance — ScriptInstance adapter
// ---------------------------------------------------------------------------

/// A `ScriptInstance` implementation backed by the tree-walk interpreter.
pub struct GDScriptInstance {
    interpreter: Interpreter,
    script_name: String,
    /// Exported-variable hint metadata (`@export*` annotations), surfaced via
    /// [`list_properties`](ScriptInstance::list_properties) so the editor
    /// inspector can render the right property editor (pat-nzgdu.5).
    exports: Vec<ExportInfo>,
}

impl GDScriptInstance {
    /// Creates a new `GDScriptInstance` by parsing and executing the given
    /// source to register its top-level function definitions and variables.
    pub fn from_source(name: &str, source: &str) -> Result<Self, RuntimeError> {
        let mut interpreter = Interpreter::new();
        interpreter.run(source)?;
        // Collect the script's `@export` hint metadata via a throwaway pass:
        // `run_class` extracts the class structure (vars/exports) without
        // disturbing the interpreter executed above. Empty for scripts with no
        // class-level exports (pat-nzgdu.5).
        let exports = Interpreter::new()
            .run_class(source)
            .map(|c| c.exports)
            .unwrap_or_default();
        Ok(Self {
            interpreter,
            script_name: name.to_string(),
            exports,
        })
    }
}

impl ScriptInstance for GDScriptInstance {
    fn call_method(&mut self, name: &str, args: &[Variant]) -> Result<Variant, ScriptError> {
        self.interpreter
            .call_user_func(name, args)
            .map_err(|e| match e.kind {
                RuntimeErrorKind::UndefinedFunction(n) => ScriptError::MethodNotFound(n),
                RuntimeErrorKind::TypeError(msg) => ScriptError::TypeError(msg),
                other => ScriptError::TypeError(other.to_string()),
            })
    }

    fn get_property(&self, name: &str) -> Option<Variant> {
        self.interpreter.environment.get(name).ok()
    }

    fn set_property(&mut self, name: &str, value: Variant) -> bool {
        self.interpreter.environment.set(name, value).is_ok()
    }

    fn list_methods(&self) -> Vec<MethodInfo> {
        self.interpreter
            .function_registry
            .iter()
            .map(|(name, func)| MethodInfo {
                name: name.clone(),
                argument_names: func.params.clone(),
                return_type: gdvariant::variant::VariantType::Nil,
                flags: MethodFlags::NORMAL,
            })
            .collect()
    }

    fn list_properties(&self) -> Vec<ScriptPropertyInfo> {
        let scope = &self.interpreter.environment.scopes[0];
        scope
            .iter()
            .map(|(name, val)| {
                // Attach `@export` hint metadata (pat-nzgdu.5) when this
                // property was exported, so the inspector renders the right
                // editor; non-exported vars report PROPERTY_HINT_NONE.
                let (hint, hint_string) = self
                    .exports
                    .iter()
                    .find(|e| &e.name == name)
                    .map(|e| (e.hint, e.hint_string.clone()))
                    .unwrap_or((PROPERTY_HINT_NONE, String::new()));
                ScriptPropertyInfo {
                    name: name.clone(),
                    property_type: val.variant_type(),
                    default_value: val.clone(),
                    hint,
                    hint_string,
                }
            })
            .collect()
    }

    fn get_script_name(&self) -> &str {
        &self.script_name
    }
}

